import React, { useRef, useState, useEffect } from 'react'
import { Table, Space } from 'antd';

export default function Req_Table(props) {

    let { data } = props

    // 我的群组表格格式
    const columns = [
        {
            title: '用户名',
            dataIndex: 'userName',
            key: 'userName',
        },
        {
            title: '操作',
            key: 'action',
            render: (_, record) => (
                <Space size="middle">
                    <a>接受</a>
                    <a>拒绝</a>
                </Space>
            ),
        },
    ];

    return (
        <>
            <Table columns={columns} dataSource={data} size="small" pagination={{ defaultPageSize: 6 }}/>
        </>
    )
}
