import React, { useRef, useState, useEffect } from 'react'
import '../../../../assets/style/Home/Home_comp/OtherT/Join_area_box.scss'
import { PubSub } from 'pubsub-js';
import { message, notification } from 'antd';
import {
    BlockOutlined
} from '@ant-design/icons';
import { postGroupRequest } from '../../../../request/request'
// import {
//     CheckCircleOutlined, CloseCircleOutlined, UsergroupAddOutlined
// } from '@ant-design/icons';

export default function Join_area_box() {

    const [join_in_showing, set_join_in_showing] = useState(false)
    const [apply_in_showing, set_apply_in_showing] = useState(false)
    const [in_zone_info, set_in_zone_info] = useState({})
    const [apply_zone_info, set_apply_zone_info] = useState({})
    const [zone_out_stateObj, set_zone_out_stateObj] = useState()
    const [keyboard_interact_stateObj, set_keyboard_interact_stateObj] = useState()
    const [is_chatting_in_zone, set_is_chatting_in_zone] = useState(false);

    useEffect(() => {
        let zone_in_token = PubSub.subscribe('zone_in', (_, stateObj) => {
            set_join_in_showing({
                ident: new Date().getTime(),
                showing: true
            })
            set_in_zone_info(stateObj.zone_info)
            // set_area_Info(stateObj.target_user_info)
        })

        let zone_in_deny_token = PubSub.subscribe('zone_in_deny', (_, stateObj) => {
            set_apply_in_showing({
                ident: new Date().getTime(),
                showing: true
            })
            set_apply_zone_info(stateObj.zone_info)
            // set_area_Info(stateObj.target_user_info)
        })

        let zone_out_token = PubSub.subscribe('zone_out', (_, stateObj) => {
            set_zone_out_stateObj(stateObj)
            set_join_in_showing({
                ident: new Date().getTime(),
                showing: false
            })
            // set_in_zone_info(stateObj.zone_info)
            // set_area_Info(stateObj.target_user_info)
        })

        let keyboard_interact_token = PubSub.subscribe('keyboard_interact', (_, stateObj) => {
            set_keyboard_interact_stateObj(stateObj)
        })

        return () => {
            PubSub.unsubscribe(zone_in_token);
            PubSub.unsubscribe(zone_in_deny_token);
            PubSub.unsubscribe(zone_out_token);
            PubSub.unsubscribe(keyboard_interact_token);
        }
    }, [])

    useEffect(() => {
        if (is_chatting_in_zone)
            PubSub.publish('chat_status', { chatting: false, targetType: "ZONE" })
    }, [zone_out_stateObj])

    useEffect(() => {
        console.log(keyboard_interact_stateObj);
        if (keyboard_interact_stateObj) {
            if (keyboard_interact_stateObj.type === 'space' && join_in_showing.showing) {
                resolve_join();
            } else if (keyboard_interact_stateObj.type === 'space' && apply_in_showing.showing) {
                resolve_apply();
            }
        }
    }, [keyboard_interact_stateObj])

    // 拒绝加入聊天
    const reject_join = () => {
        set_is_chatting_in_zone(false)
        PubSub.publish('zone_in_ack', { state: false })
        set_join_in_showing(false)
    }

    // 确定加入聊天
    const resolve_join = () => {
        set_is_chatting_in_zone(true)
        PubSub.publish('zone_in_ack', { state: true })
        PubSub.publish('chat_status', { chatting: true, targetType: "ZONE", zone_info: in_zone_info.zone })
        set_join_in_showing({
            ident: new Date().getTime(),
            showing: false
        })
    }

    // 确定申请进入群组
    const resolve_apply = () => {
        console.log(apply_zone_info);
        let senderId = parseInt(sessionStorage.getItem('userId'));
        let targetId = apply_zone_info.groupId;

        let sendForm = new FormData();
        sendForm.append('senderId',senderId)
        sendForm.append('targetId',targetId)
        postGroupRequest(sendForm).then(res=>{
            console.log(res);
            message.success('群组申请发送成功')
            set_apply_in_showing({
                ident: new Date().getTime(),
                showing: false
            })
        }).catch(err=>{
            console.error(err);
        })

    }

    useEffect(() => {
        const placement = 'bottomLeft'
        if (join_in_showing.showing) {
            notification.info({
                message: <p>你正处在 <u>{in_zone_info.zone.groupName}</u> 聊天区域</p>,
                description: <p>按下空格<span className='_keyboard_' id='space_keyboard'>Space</span>表示<span style={{ color: '#40b8c3' }}>直接进入</span></p>,
                placement,
                duration: 0,
                icon: <BlockOutlined style={{ color: '#40b8c3' }} />
            });
        } else {
            notification.destroy();
        }
    }, [join_in_showing])

    useEffect(() => {
        const placement = 'bottomLeft'
        if (apply_in_showing.showing) {
            notification.info({
                message: <p>你正处在 <u>{apply_zone_info.groupName}</u> 聊天区域</p>,
                description: <p>按下空格<span className='_keyboard_' id='space_keyboard'>Space</span>表示<span style={{ color: '#db5500' }}>申请进入</span></p>,
                placement,
                duration: 0,
                icon: <BlockOutlined style={{ color: '#db5500' }} />
            });
        } else {
            notification.destroy();
        }
    }, [apply_in_showing])



    return (
        <>
        </>
    )
}
